; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jr z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 14: Print "1 started"
			dw kw_printstrvar, str0
			dw kw_printnl

			; main.bas 15: Wait
			dw p_wait_c

			; main.bas 16: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str1, var_filesystem_capability_capability
			dw kw_printstrvar, str2
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str3, var_filesystem_capability_capability
			dw kw_printstrvar, str4
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 17: Wait
			dw p_wait_c

			; main.bas 18: Print "3 Devices: "; FileSystem.Devices()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printstrvar, str5
			dw kw_printstrvar, var_filesystem_devices_devices
			dw kw_printnl

			; main.bas 19: Wait
			dw p_wait_c

			; main.bas 20: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printstrvar, str6
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printstrvar, str7
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 21: Wait
			dw p_wait_c

			; main.bas 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 23: Print "5 Save STEP.DAT..."
			dw kw_printstrvar, str8
			dw kw_printnl

			; main.bas 24: Wait
			dw p_wait_c

			; main.bas 25: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str9, vp_arr_a, lit_20, var_r

			; main.bas 26: Print "  Save gave"; r
			dw kw_printstrvar, str10
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 27: Wait
			dw p_wait_c

			; main.bas 28: Print "6 Load STEP.DAT..."
			dw kw_printstrvar, str11
			dw kw_printnl

			; main.bas 29: Wait
			dw p_wait_c

			; main.bas 30: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str9, vp_arr_b, lit_20, var_r

			; main.bas 31: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printstrvar, str12
			dw kw_printint, var_r
			dw kw_printstrvar, str13
			dw kw_printint, arr_b
			dw kw_printstrvar, str14
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 32: Print "7 done"
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 33: End
			dw kw_printnl0
			dw kw_printstrvar, str16
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 36: Print "  (press a key)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 37: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; main.bas 38: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_capability:		; function capability (asm keyword), FileSystem.cls line 39
            pop hl		; FileSystem.cls 40
            pop de		; FileSystem.cls 41
            ld bc, fn_filesystem_capability_caps		; FileSystem.cls 42
            jp ntc_capfind		; FileSystem.cls 43
fn_filesystem_capability_caps:       db "LOAD", 0		; FileSystem.cls 44
            dw -1		; FileSystem.cls 45
            db "SAVE", 0		; FileSystem.cls 46
            dw -1		; FileSystem.cls 47
            db "SEQUENTIAL", 0		; FileSystem.cls 48
            dw -1		; FileSystem.cls 49
            db "DEVICES", 0		; FileSystem.cls 50
            dw -1		; FileSystem.cls 51
            db "VOLUMES", 0		; FileSystem.cls 52
            dw -1		; FileSystem.cls 53
            db "ROMDISC", 0		; FileSystem.cls 54
            dw -1		; FileSystem.cls 55
            db "MAXOPEN", 0		; FileSystem.cls 56
            dw 1		; FileSystem.cls 57
            db 0		; FileSystem.cls 58
			ret			; end of #asm

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 65
            pop hl		; FileSystem.cls 66
            ld (fs_a1), hl		; FileSystem.cls 67
            pop hl		; FileSystem.cls 68
            ld e, (hl)		; FileSystem.cls 69
            inc hl		; FileSystem.cls 70
            ld d, (hl)		; FileSystem.cls 71
            ld (fs_a2), de		; FileSystem.cls 72
            pop hl		; FileSystem.cls 73
            ld e, (hl)		; FileSystem.cls 74
            inc hl		; FileSystem.cls 75
            ld d, (hl)		; FileSystem.cls 76
            ld (fs_a3), de		; FileSystem.cls 77
            pop hl		; FileSystem.cls 78
            ld (fs_res), hl		; FileSystem.cls 79
            ld hl, fs_load		; FileSystem.cls 80
            ld de, rd_load		; FileSystem.cls 81
            jp rd_route		; FileSystem.cls 82
			ret			; end of #asm

fn_filesystem_save:		; function save (asm keyword), FileSystem.cls line 88
            pop hl		; FileSystem.cls 89
            ld (fs_a1), hl		; FileSystem.cls 90
            pop hl		; FileSystem.cls 91
            ld e, (hl)		; FileSystem.cls 92
            inc hl		; FileSystem.cls 93
            ld d, (hl)		; FileSystem.cls 94
            ld (fs_a2), de		; FileSystem.cls 95
            pop hl		; FileSystem.cls 96
            ld e, (hl)		; FileSystem.cls 97
            inc hl		; FileSystem.cls 98
            ld d, (hl)		; FileSystem.cls 99
            ld (fs_a3), de		; FileSystem.cls 100
            pop hl		; FileSystem.cls 101
            ld (fs_res), hl		; FileSystem.cls 102
            ld hl, fs_save		; FileSystem.cls 103
            ld de, rd_ns		; FileSystem.cls 104
            jp rd_route		; FileSystem.cls 105
			ret			; end of #asm

fn_filesystem_devices:		; function devices (asm keyword), FileSystem.cls line 326
            pop hl		; FileSystem.cls 327
            ld (fs_res), hl		; FileSystem.cls 328
            ld hl, fs_devices		; FileSystem.cls 329
            jp fs_go0		; FileSystem.cls 330
			ret			; end of #asm

fn_filesystem_currentdevice:		; function currentdevice (asm keyword), FileSystem.cls line 336
            pop hl		; FileSystem.cls 337
            ld (fs_res), hl		; FileSystem.cls 338
            ld hl, fs_curdev		; FileSystem.cls 339
            jp fs_go0		; FileSystem.cls 340
			ret			; end of #asm

fn_filesystem_currentvolume:		; function currentvolume (asm keyword), FileSystem.cls line 369
            pop hl		; FileSystem.cls 370
            ld (fs_res), hl		; FileSystem.cls 371
            ld hl, fs_curvol		; FileSystem.cls 372
            jp fs_go0		; FileSystem.cls 373
			ret			; end of #asm


; ============================================================
; Variables
